#include <array>

using Board = std::array<std::array<char, 3>, 3>;

bool hasWon(const Board& board, char player)
{
    for (std::size_t i{ 0 }; i < 3; ++i)
    {
        if (board[i][0] == player && board[i][1] == player && board[i][2] == player) return true;
        if (board[0][i] == player && board[1][i] == player && board[2][i] == player) return true;
    }
    if (board[0][0] == player && board[1][1] == player && board[2][2] == player) return true;
    if (board[0][2] == player && board[1][1] == player && board[2][0] == player) return true;
    return false;
}

unitTests:
Board make(const char* cells) { Board b{}; for (std::size_t i{ 0 }; i < 9; ++i) b[i / 3][i % 3] = cells[i]; return b; }
TEST("a row") { CHECK(hasWon(make("XXX"
                                  "O.O"
                                  "..."), 'X')); CHECK(hasWon(make("O.X" ".X." "OOO"), 'O')); }
TEST("a column") { CHECK(hasWon(make("X.O" "X.O" "X.."), 'X')); CHECK(hasWon(make("X.O" "..O" "X.O"), 'O')); }
TEST("both diagonals") { CHECK(hasWon(make("X.O" ".X." "O.X"), 'X')); CHECK(hasWon(make("X.O" ".O." "O.X"), 'O')); }
TEST("no winner") { CHECK(!hasWon(make("XOX" "XOO" "OXX"), 'X')); CHECK(!hasWon(make("XOX" "XOO" "OXX"), 'O')); CHECK(!hasWon(make("........."), 'X')); }
TEST("the other player's line does not count") { CHECK(!hasWon(make("XXX" "O.O" "..."), 'O')); }

